"use client";

import * as React from "react";
import { cn } from "@/lib/utils";

export type FooterSectionTheme = "dark" | "light" | "custom";

export interface FooterSectionLink {
  label: string;
  url: string;
}

export interface FooterSectionColumn {
  title: string;
  links: FooterSectionLink[];
}

export interface FooterSectionCustomColors {
  bg?: string;
  fg?: string;
  headingColor?: string;
  linkColor?: string;
  copyrightColor?: string;
  createdByColor?: string;
}

export interface FooterSectionProps {
  theme?: FooterSectionTheme;
  customColors?: FooterSectionCustomColors;
  columns?: FooterSectionColumn[];
  accentColor?: string;
  hoverUnderline?: boolean;
  copyrightText?: string;
  createdByText?: string;
  createdByUrl?: string;
  className?: string;
}

const DEFAULT_COLUMNS: FooterSectionColumn[] = [
  { title: "Navigate", links: [{ label: "Home", url: "#" }, { label: "About", url: "#" }, { label: "Services", url: "#" }, { label: "Team", url: "#" }] },
  { title: "Resources", links: [{ label: "Case Studies", url: "#" }, { label: "How We Work", url: "#" }, { label: "FAQ", url: "#" }, { label: "News", url: "#" }] },
  { title: "Connect", links: [{ label: "Book a Call", url: "#" }, { label: "Twitter", url: "#" }, { label: "Instagram", url: "#" }] },
  { title: "Legal", links: [{ label: "Privacy Policy", url: "#" }, { label: "Terms of Service", url: "#" }, { label: "Cookie Policy", url: "#" }] },
];

function FooterLinkItem({
  link,
  fg,
  accentColor,
  showUnderline,
  mutedColor,
}: {
  link: FooterSectionLink;
  fg?: string;
  accentColor: string;
  showUnderline: boolean;
  mutedColor: string;
}) {
  const [active, setActive] = React.useState(false);
  const color = showUnderline ? (fg ?? mutedColor) : active ? accentColor : (fg ?? mutedColor);
  return (
    <a
      href={link.url}
      onMouseEnter={() => setActive(true)}
      onMouseLeave={() => setActive(false)}
      onFocus={() => setActive(true)}
      onBlur={() => setActive(false)}
      className="fs-link"
      style={{ color, boxShadow: active ? `0 0 0 2px ${accentColor}40` : "none", borderRadius: 2, transition: "color 200ms ease, box-shadow 150ms ease" }}
    >
      {link.label}
      {showUnderline && (
        <span
          className="fs-underline"
          style={{ background: accentColor, transform: active ? "scaleX(1)" : "scaleX(0)" }}
        />
      )}
    </a>
  );
}

function CreatedByLink({ text, url, fg, mutedColor, activeColor }: { text: string; url: string; fg?: string; mutedColor: string; activeColor: string }) {
  const [active, setActive] = React.useState(false);
  return (
    <a
      href={url}
      onMouseEnter={() => setActive(true)}
      onMouseLeave={() => setActive(false)}
      onFocus={() => setActive(true)}
      onBlur={() => setActive(false)}
      className="fs-createdby"
      style={{
        color: fg ?? (active ? activeColor : mutedColor),
        boxShadow: active ? `0 0 0 2px color-mix(in srgb, currentColor 19%, transparent)` : "none",
        borderRadius: 2,
        transition: "color 200ms ease, box-shadow 150ms ease",
      }}
    >
      {text}
    </a>
  );
}

export function FooterSection({
  theme = "dark",
  customColors,
  columns = DEFAULT_COLUMNS,
  accentColor = "#c44b2b",
  hoverUnderline = true,
  copyrightText = "© 2026 Studio. All rights reserved.",
  createdByText = "Built with ReactFrame",
  createdByUrl = "https://reactframe.com",
  className,
}: FooterSectionProps) {
  const uid = React.useId().replace(/:/g, "");
  const isCustom = theme === "custom";
  const isDark = theme === "dark";

  const bg = isCustom ? (customColors?.bg ?? "#1a1a2e") : isDark ? "#0e0e0e" : "#f5f4f1";
  const fg = isCustom ? (customColors?.fg ?? "#ffffff") : isDark ? "#f5f4f1" : "#0e0e0e";
  const baseFgRgb = isDark || isCustom ? "245,244,241" : "14,14,14";
  const linkMuted = `rgba(${baseFgRgb}, 0.6)`;
  const copyrightMuted = `rgba(${baseFgRgb}, 0.45)`;
  const createdByActive = `rgba(${baseFgRgb}, 1)`;
  const borderColor = isCustom ? `${customColors?.fg ?? "#ffffff"}14` : `rgba(${baseFgRgb}, 0.08)`;

  return (
    <footer
      role="contentinfo"
      data-fs={uid}
      className={cn("fs-root", className)}
      style={{
        background: bg,
        color: fg,
        transition: "background-color 600ms cubic-bezier(0.16, 1, 0.3, 1), color 600ms cubic-bezier(0.16, 1, 0.3, 1)",
      }}
    >
      <style>{`
        [data-fs="${uid}"].fs-root { position: relative; width: 100%; }
        [data-fs="${uid}"] .fs-container { margin: 0 auto; max-width: 1280px; padding: 48px 24px; }
        [data-fs="${uid}"] .fs-nav { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); column-gap: 32px; row-gap: 40px; }
        [data-fs="${uid}"] .fs-column { display: flex; flex-direction: column; }
        [data-fs="${uid}"] .fs-column-title { margin: 0 0 18px 0; font-size: 15px; font-weight: 600; letter-spacing: -0.01em; }
        [data-fs="${uid}"] .fs-column-links { margin: 0; padding: 0; display: flex; list-style: none; flex-direction: column; gap: 14px; }
        [data-fs="${uid}"] .fs-link { position: relative; display: inline-flex; width: fit-content; padding-bottom: 2px; font-size: 14px; text-decoration: none; outline: none; }
        [data-fs="${uid}"] .fs-underline { position: absolute; bottom: 0; left: 0; height: 1px; width: 100%; transform-origin: left; transition: transform 300ms cubic-bezier(0.16,1,0.3,1); }
        [data-fs="${uid}"] .fs-createdby { font-size: 13px; text-decoration: none; outline: none; }
        [data-fs="${uid}"] .fs-bottom-bar { margin-top: 48px; display: flex; flex-direction: column; align-items: flex-start; justify-content: space-between; gap: 8px; border-top-width: 1px; border-top-style: solid; padding-top: 24px; }
        [data-fs="${uid}"] .fs-copyright { font-size: 13px; }
        @media (min-width: 640px) {
          [data-fs="${uid}"] .fs-container { padding: 64px 48px; }
          [data-fs="${uid}"] .fs-nav { display: flex; justify-content: space-between; gap: 32px; }
          [data-fs="${uid}"] .fs-bottom-bar { margin-top: 56px; flex-direction: row; align-items: center; gap: 0; }
        }
      `}</style>

      <div className="fs-container">
        <nav aria-label="Footer navigation" className="fs-nav">
          {columns.map((group, gi) => (
            <div key={gi} className="fs-column">
              <h2 className="fs-column-title" style={{ color: customColors?.headingColor }}>
                {group.title}
              </h2>
              <ul className="fs-column-links">
                {group.links.map((link, li) => (
                  <li key={li}>
                    <FooterLinkItem
                      link={link}
                      fg={isCustom ? customColors?.linkColor : undefined}
                      accentColor={accentColor}
                      showUnderline={hoverUnderline}
                      mutedColor={linkMuted}
                    />
                  </li>
                ))}
              </ul>
            </div>
          ))}
        </nav>

        <div className="fs-bottom-bar" style={{ borderColor }}>
          <span className="fs-copyright" style={{ color: isCustom ? (customColors?.copyrightColor ?? copyrightMuted) : copyrightMuted }}>
            {copyrightText}
          </span>
          {createdByText && (
            <CreatedByLink
              text={createdByText}
              url={createdByUrl}
              fg={isCustom ? customColors?.createdByColor : undefined}
              mutedColor={linkMuted}
              activeColor={createdByActive}
            />
          )}
        </div>
      </div>
    </footer>
  );
}

